export function evaluate({ inputs, time }) {
  const g = 9.8;
  const u = inputs.launchSpeed;
  const T = 2 * u / g;
  const t = sdk.clamp(time, 0, T);
  const v = u - g * t;
  const h = Math.max(0, u * t - g * t * t / 2);
  const apexTime = u / g;
  const apexHeight = u * u / (2 * g);
  const base = 360, top = 90;
  const sy = (base - top) / 1.4;
  const y = base - h * sy;
  const bx = 300;
  const atTop = Math.abs(v) < 0.02;
  const state = atTop ? 'Still for an instant' : (v > 0 ? 'Moving up' : 'Moving down');
  const objs = [];
  objs.push(...sdk.panel({ id: 'lane.toss', x: 20, y: 40, w: 600, h: 360, title: 'Vertical toss', state: state }));
  objs.push(sdk.axis('axis.height', { x: 90, y: base + 12, length: top ? base - top + 12 : 0, orientation: 'y', min: 0, max: 1.4, ticks: 7, label: 'Height', unit: 'm' }));
  objs.push(sdk.line('guide.launch', 150, base + 12, 450, base + 12, { role: 'neutral' }));
  objs.push(sdk.circle('ball.toss', bx, y, 24, { role: 'output' }));
  const vv = atTop ? 0 : v;
  objs.push(...sdk.vector('vec.v', { x: bx - 40, y: y }, { value: vv, direction: 'up' }, { scale: 22, label: 'v', role: 'input' }));
  objs.push(...sdk.vector('vec.a', { x: bx + 40, y: y }, { value: -g, direction: 'up' }, { scale: 5, label: 'a', role: 'warning' }));
  objs.push(...sdk.callout(bx + 80, y - 20, [state, 'Gravity pulls down'], { id: 'callout.toss' }));
  return {
    frame: { width: 640, height: 420, objects: objs, readouts: [{ id: 'motionState', value: state }, { id: 'gravityState', value: 'Gravity pulls down' }] },
    quantities: { launchSpeed: u, gravity: g, apexTime, apexHeight, velocity: v, height: h }
  };
}
